import{_ as e,o as a,c as r,al as o}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"Hardware Simulation","description":"","frontmatter":{},"headers":[],"relativePath":"uk/simulation/hardware.md","filePath":"uk/simulation/hardware.md"}'),i={name:"uk/simulation/hardware.md"};function n(s,t,d,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="hardware-simulation" tabindex="-1">Hardware Simulation <a class="header-anchor" href="#hardware-simulation" aria-label="Permalink to &quot;Hardware Simulation&quot;">​</a></h1><p>PX4 can run simulation directly on a real flight controller, replacing real sensors with simulated data, while otherwise executing the full flight stack on actual autopilot hardware.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Simulating PX4 on flight controller hardware exercises more flight stack code than SITL, and tests more of your hardware integration. It can surface issues with running PX4 that might hidden when running on a desktop OS and hardware, or even a different flight controller board.</p></div><p>Two simulation approaches are available, controlled by the <a href="./../advanced_config/parameter_reference#SYS_HITL">SYS_HITL</a> parameter:</p><ul><li><strong><a href="./../simulation/hitl">HITL Simulation</a> (<code>SYS_HITL=1</code>):</strong> An external simulator (Gazebo Classic or jMAVSim) runs physics on a companion computer and sends sensor data to the flight controller via MAVLink HIL messages. Requires a USB/UART connection and simulator setup.</li><li><strong><a href="./../sim_sih/hardware">SIH on Hardware</a> (<code>SYS_HITL=2</code>):</strong> A C++ physics model runs directly on the flight controller itself. No external simulator, no companion computer, no MAVLink sensor data. Just set the parameter and reboot.</li></ul><h2 id="comparision" tabindex="-1">HITL vs SIH <a class="header-anchor" href="#comparision" aria-label="Permalink to &quot;HITL vs SIH {#comparision}&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>HITL (<code>SYS_HITL=1</code>)</th><th>SIH (<code>SYS_HITL=2</code>)</th></tr></thead><tbody><tr><td>Physics model</td><td>External simulator (Gazebo Classic, jMAVSim)</td><td>Internal C++ module</td></tr><tr><td>Communication</td><td>MAVLink HIL messages</td><td>uORB (internal)</td></tr><tr><td>External process</td><td>Вимоги</td><td>Not required</td></tr><tr><td>Setup complexity</td><td>Higher</td><td>Lower</td></tr><tr><td>Sensor simulation</td><td>Camera, lidar, etc. (via simulator)</td><td>IMU, GPS, baro, mag, airspeed only</td></tr><tr><td>Vehicle types</td><td>Quadcopter, Standard VTOL</td><td>Quad, Hex, FW, VTOL Tailsitter, Standard VTOL, Rover</td></tr></tbody></table><h2 id="when-to-use-which" tabindex="-1">When to Use Which <a class="header-anchor" href="#when-to-use-which" aria-label="Permalink to &quot;When to Use Which&quot;">​</a></h2><ul><li>Use <strong>SIH</strong> if you want the simplest possible setup. No external dependencies.</li><li>Use <strong>HITL</strong> if you need an external physics engine, 3D visualization from Gazebo Classic, or camera/lidar sensor simulation that SIH does not provide.</li></ul>',9)])])}const p=e(i,[["render",n]]);export{m as __pageData,p as default};
